local M = class("CastingSwordExchangeControl",LikeOO.OOControlBase)

function M:onEnter()
end

function M:onHandle(msg , data)
    if msg == 99999 then
        self:closeView()
    elseif msg == "btn_closeBtn" then
        self:closeView()
    elseif msg == "btn_exchangeTabBtn" then
        self.m_view:switchTab(2)
    elseif msg == "btn_signBtn" then
        self.m_view:switchTab(1)
    elseif msg == "btn_shareBtn" then
        -- 分享按钮
        self:openView("SharePoster", {version = self.m_model.m_version, picture_id = self.m_model.m_spokesmanIndex})
    end
end

function M:activityOverExamine(response)
    if response["end"] == 1 then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
        self:closeView()
        return true
    end
    return false
end

function M:destroy()
    M.super.destroy(self)
end

return M